INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Ashtabhaiava Homam-te', 'Ashtabhaiava Homam', 'te', 'అష్టభైరవ ఆపదుద్ధారక రక్షాహోమం', 'కాలాష్టమి ప్రత్యేకం — భైరవ మూలమంత్రాల నడుమ 8 కిలోల మిరియాలతో అష్టభైరవులకు హోమాహుతులు, ఆపదల నుండి రక్షణ కోసం.', 'Vikranta Bhairava Temple', 'Saturday, 05 September', '2026-09-05T07:00:00+05:30', 1500, 1500, 'All', 'assets/images/pujas/bhairava.jpg', '{"mantra":"OM BHAIRAVAYA NAMAHA","about":"కాలష్టమి అనేది శివుని ఉగ్ర రక్షక రూపమైన కాలభైరవుడిని ఆరాధించే పర్వదినం. ఈ శక్తివంతమైన హోమంలో, మీ పేరుతో సంకల్పం చేసి, ప్రమాదాలు, అడ్డంకులు మరియు ప్రతికూల శక్తుల నుండి రక్షణను కోరుతూ... వేద పండితులు భైరవ మూల మంత్రాన్ని పఠిస్తుండగా, ఎనిమిది మంది భైరవులకు 8 కిలోల మిరియాలను హవిస్సుగా సమర్పిస్తారు.","tradition":"శైవ తాంత్రిక సంప్రదాయం","duration":"సుమారు 2.5 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Navanarasimha Homam-en', 'Navanarasimha Homam', 'en', 'Navanarasimha Homam', 'A Kamika Ekadashi special homam to the nine forms of Lord Narasimha, performed with your name and gotram for divine grace and protection.', 'Venkateswara Swamy Temple', 'Sunday, 9 August', '2026-08-09T08:00:00+05:30', 816, 999, 'All', 'assets/images/pujas/narasimha.jpg', '{"mantra":"OM NARASIMHAYA NAMAHA","about":"On the sacred occasion of Kamika Ekadashi, this homam invokes the nine forms of Lord Narasimha — protector against fear and evil. With your name and gotram included in the sankalpam, Vedic priests perform the full ritual seeking divine grace, courage, and protection for you and your family.","tradition":"Vaishnava Vedic Tradition","duration":"Approx. 2 hours","forWhom":"Individual or Family"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Navanarasimha Homam-te', 'Navanarasimha Homam', 'te', 'నవనారసింహ హోమం', 'కామిక ఏకాదశి ప్రత్యేకం — భక్తుల పేరు, గోత్రంతో నవనరసింహ స్వామివారికి ప్రత్యేక హోమ ఆరాధన, దైవానుగ్రహం కోసం.', 'Venkateswara Swamy Temple', 'Sunday, 9 August', '2026-08-09T08:00:00+05:30', 816, 999, 'All', 'assets/images/pujas/narasimha.jpg', '{"mantra":"OM NARASIMHAYA NAMAHA","about":"On the sacred occasion of Kamika Ekadashi, this homam invokes the nine forms of Lord Narasimha — protector against fear and evil. With your name and gotram included in the sankalpam, Vedic priests perform the full ritual seeking divine grace, courage, and protection for you and your family.","tradition":"వైష్ణవ వైదిక సంప్రదాయం","duration":"సుమారు 2 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Venkateswara Swamy Abhishekam-en', 'Venkateswara Swamy Abhishekam', 'en', 'Venkateswara Swamy Abhishekam (108 Substances)', 'A grand Kamika Ekadashi abhishekam to Sri Venkateswara Swamy with 108 sacred substances, sankalpam taken with your gotra and name.', 'Venkateswara Swamy Temple', 'Sunday, 9 August', '2026-08-09T09:00:00+05:30', 816, 999, 'All', 'assets/images/pujas/venkateswara.jpg', '{"mantra":"OM NAMO VENKATESAYA","about":"This grand abhishekam bathes Sri Venkateswara Swamy in 108 sacred substances — milk, honey, sandalwood, sacred waters and more — while Vedic mantras are chanted continuously. Your sankalpam, taken with your gotra and name, carries your prayers directly into this deeply auspicious Kamika Ekadashi ritual.","tradition":"Vaishnava Vedic Tradition","duration":"Approx. 2.5 hours","forWhom":"Individual or Family"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Venkateswara Swamy Abhishekam-te', 'Venkateswara Swamy Abhishekam', 'te', 'వెంకటేశ్వర స్వామి అభిషేకం (108 ద్రవ్యాలు)', 'కామిక ఏకాదశి ప్రత్యేకం — భక్తుల గోత్రనామాలతో సంకల్పం చేసి, వేదమంత్రాల నడుమ శ్రీ వేంకటేశ్వర స్వామికి 108 ద్రవ్యాలతో మహా అభిషేకం.', 'Venkateswara Swamy Temple', 'Sunday, 9 August', '2026-08-09T09:00:00+05:30', 816, 999, 'All', 'assets/images/pujas/venkateswara.jpg', '{"mantra":"OM NAMO VENKATESAYA","about":"వేద మంత్రాల నిరంతర పఠన మధ్య, పాలు, తేనె, గంధం, పవిత్ర జలాలు వంటి 108 పవిత్ర ద్రవ్యాలతో శ్రీ వేంకటేశ్వర స్వామికి ఈ వైభవయుతమైన అభిషేకం నిర్వహించబడుతుంది. మీ గోత్రనామాలతో కూడిన మీ సంకల్పం, అత్యంత పవిత్రమైన ఈ ''కామిక ఏకాదశి'' విశేష పూజా కార్యక్రమంలో మీ ప్రార్థనలను నేరుగా చేరవేస్తుంది.","tradition":"వైష్ణవ వైదిక సంప్రదాయం","duration":"సుమారు 2.5 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Venkateswara Swamy Abhishekam-hi', 'Venkateswara Swamy Abhishekam', 'hi', 'वेंकटेश्वर स्वामी अभिषेकम (108 द्रव्य)', 'कामिका एकादशी विशेष — भक्तों के गोत्र-नाम से संकल्प कर, वैदिक मंत्रों के बीच श्री वेंकटेश्वर स्वामी को 108 द्रव्यों से महा अभिषेक।', 'Venkateswara Swamy Temple', 'Sunday, 9 August', '2026-08-09T09:00:00+05:30', 816, 999, 'All', 'assets/images/pujas/venkateswara.jpg', '{"mantra":"OM NAMO VENKATESAYA","about":"इस भव्य अभिषेक में श्री वेंकटेश्वर स्वामी को 108 पवित्र चीज़ों — जैसे दूध, शहद, चंदन, पवित्र जल आदि — से स्नान कराया जाता है और साथ ही लगातार वैदिक मंत्रों का जाप किया जाता है। आपके गोत्र और नाम के साथ लिया गया आपका संकल्प, आपकी प्रार्थनाओं को सीधे इस बेहद शुभ कामिका एकादशी अनुष्ठान तक पहुँचाता है।","tradition":"वैष्णव वैदिक परंपरा","duration":"लगभग 2.5 घंटे","forWhom":"व्यक्ति या परिवार"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('నవనాగ హోమం-te', 'నవనాగ హోమం', 'te', 'నవనాగ హోమం', 'నాగపంచమి ప్రత్యేకం — నాగదేవతల అనుగ్రహం, కుటుంబ శ్రేయస్సు, ఆయురారోగ్యం, కార్యసిద్ధి కోసం నిర్వహించే శాస్త్రోక్త నవనాగ హోమం.', 'Basaveshwara Temple, Kukke Kshetra', 'Monday, 17 August', '2026-08-17T07:30:00+05:30', 816, NULL, 'All', 'assets/images/pujas/naga.jpg', '{"mantra":"OM NAGADEVATABHYO NAMAHA","about":"On the auspicious occasion of Naga Panchami, the nine Naga deities are invoked in this scripturally-ordained homam at the sacred Kukke Kshetra. Your sankalpam is included in the ritual, seeking the grace of the Nagas for family well-being, health, and the removal of Naga dosha.","tradition":"వైదిక నాగారాధన సంప్రదాయం","duration":"సుమారు 2 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('భూ వరాహ హోమం & మహాభిషేకం-te', 'భూ వరాహ హోమం & మహాభిషేకం', 'te', 'భూ వరాహ హోమం & మహాభిషేకం', 'కామిక ఏకాదశి ప్రత్యేకం — భూ, గృహ శ్రేయస్సు, జీవితంలో స్థిరత్వం కోసం నిర్వహించే శాస్త్రోక్త భూ వరాహ హోమం, మహాభిషేకం.', 'Bhu Varaha Swamy Temple', 'Sunday, 9 August', '2026-08-09T07:00:00+05:30', 816, NULL, 'Finance', 'assets/images/pujas/varaha.jpg', '{"mantra":"OM VARAHAYA NAMAHA","about":"Lord Varaha, who lifted the Earth from the cosmic waters, is invoked in this Kamika Ekadashi special ritual for stability in land, home, and life. A Mahabhishekam follows the homam, with your sankalpam seeking property harmony, removal of vastu-related obstacles, and lasting stability for your family.","tradition":"వైష్ణవ వైదిక సంప్రదాయం","duration":"సుమారు 2.5 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Go-Grasam Sankalpam-en', 'Go', 'en', 'Go-Grasam Sankalpam', 'A sacred seva performed to attain spiritual merit, peace, and divine blessings through offering food to Gomata.', 'Sri Bhramarambika Sametha Malleshwara Swamy Temple, Achampet (Guntur)', 'Sunday, 25 August', '2026-08-25T09:00:00+05:30', 51, NULL, 'All', 'assets/images/pujas/gograsam.jpg', '{"mantra":"OM SRI GOMATHRE NAMAHA","about":"Gau seva is counted among the most meritorious acts in our shastras. In this seva, fresh food is lovingly offered to Gomata after a sankalpam is taken in your name and gotram, invoking her blessings of nourishment, peace, and prosperity for your whole family.","tradition":"Vedic Smriti Tradition","duration":"Minimum 2 hours","forWhom":"Individual or Family"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Go-Grasam Sankalpam-te', 'Go', 'te', 'గో-గ్రాసం సంకల్పం', 'గోమాతకు ఆహార సమర్పణ ద్వారా పుణ్యఫలాలు, శాంతి మరియు దైవ అనుగ్రహం పొందేందుకు నిర్వహించే పవిత్ర సేవ.', 'Sri Bhramarambika Sametha Malleshwara Swamy Temple, Achampet (Guntur)', 'Sunday, 23 August', '2026-08-23T09:00:00+05:30', 51, NULL, 'All', 'assets/images/pujas/gograsam.jpg', '{"mantra":"OM SRI GOMATHRE NAMAHA","about":"Gau seva is counted among the most meritorious acts in our shastras. In this seva, fresh food is lovingly offered to Gomata after a sankalpam is taken in your name and gotram, invoking her blessings of nourishment, peace, and prosperity for your whole family.","tradition":"వైదిక స్మృతి సంప్రదాయం","duration":"కనీసం 2 గంటలు","forWhom":"వ్యక్తి లేదా కుటుంబం"}');
INSERT INTO cms_pujas (id, base_id, language, name, description, temple, date, muhurat, price, base_price, cat, image, detail) VALUES ('Go-Grasam Sankalpam-hi', 'Go', 'hi', 'गो-ग्रासम संकल्पम', 'गौमाता को भोजन अर्पित कर पुण्य, शांति और दिव्य आशीर्वाद पाने की पवित्र सेवा।', 'Sri Bhramarambika Sametha Malleshwara Swamy Temple, Achampet (Guntur)', 'Sunday, 17 August', '2026-08-18T09:00:00+05:30', 51, NULL, 'All', 'assets/images/pujas/gograsam.jpg', '{"mantra":"OM SRI GOMATHRE NAMAHA","about":"Gau seva is counted among the most meritorious acts in our shastras. In this seva, fresh food is lovingly offered to Gomata after a sankalpam is taken in your name and gotram, invoking her blessings of nourishment, peace, and prosperity for your whole family.","tradition":"वैदिक स्मृति परंपरा","duration":"न्यूनतम 2 घंटे","forWhom":"व्यक्ति या परिवार"}');
INSERT INTO cms_packages (id, name, name_te, name_hi, description, description_te, description_hi, temple, date, muhurat, price, media, badge, detail) VALUES ('Monthly Abhishekam Package', 'Monthly Abhishekam Package', 'మాసిక అభిషేకం ప్యాకేజీ', 'मासिक अभिषेक पैकेज', 'A Rudrabhishekam performed in your name every month on Masa Shivaratri, with the video delivered each time.', 'ప్రతి మాస శివరాత్రికి మీ పేరుతో రుద్రాభిషేకం — వీడియోతో సహా.', 'हर मास शिवरात्रि पर आपके नाम से रुद्राभिषेक — वीडियो सहित।', 'Rotating Shiva kshetras across India', 'Every Masa Shivaratri', '2026-12-30T08:00:00+05:30', 299, 'assets/images/packages/shiva.jpg', 'Monthly', '{"mantra":"OM NAMAH SHIVAYA","about":"Keep Lord Shiva''s blessings flowing through the year: every Masa Shivaratri, a Rudrabhishekam is performed with your sankalpam at a sacred Shiva kshetra, and the video reaches you each month."}');
INSERT INTO cms_packages (id, name, name_te, name_hi, description, description_te, description_hi, temple, date, muhurat, price, media, badge, detail) VALUES ('Sankatahara Chaturthi Package', 'Sankatahara Chaturthi Package', 'సంకటహర చతుర్థి ప్యాకేజీ', 'संकटहर चतुर्थी पैकेज', 'Ganapati puja performed every Sankatahara Chaturthi for removal of obstacles and family well-being.', 'ప్రతి సంకటహర చతుర్థికి విఘ్న నివారణ, కుటుంబ శ్రేయస్సు కోసం గణపతి పూజ.', 'हर संकटहर चतुर्थी पर विघ्न-निवारण व परिवार कल्याण हेतु गणपति पूजा।', 'Sri Ganapati Temple, Telangana', 'Every Chaturthi', '2026-08-11T08:00:00+05:30', 199, 'assets/images/packages/ganesha.jpg', 'Monthly', '{"mantra":"OM GAM GANAPATHAYE NAMAHA","about":"Sankatahara Chaturthi is the day Lord Ganesha removes sankata — troubles and obstacles. Every month on this tithi, a Ganapati puja is performed with your sankalpam for a smooth, obstacle-free life."}');
INSERT INTO cms_packages (id, name, name_te, name_hi, description, description_te, description_hi, temple, date, muhurat, price, media, badge, detail) VALUES ('Annadanam Seva Package', 'Annadanam Seva Package', 'అన్నదాన సేవా ప్యాకేజీ', 'अन्नदान सेवा पैकेज', 'Sponsor annadanam (food offering) to devotees every month in your family''s name — the greatest daanam.', 'ప్రతి నెల మీ కుటుంబం పేరుతో భక్తులకు అన్నదానం — దానాల్లో గొప్పది.', 'हर माह आपके परिवार के नाम से भक्तों को अन्नदान — दानों में श्रेष्ठ।', 'Participating temples', 'Once every month', '2026-08-20T11:00:00+05:30', 501, 'assets/images/packages/annadanam.jpg', 'Monthly', '{"mantra":"ANNADANAM MAHADANAM","about":"Annadanam — the gift of food — is praised as the greatest of all daanams. Each month, meals are served to devotees at participating temples in your family''s name, with photos shared on WhatsApp."}');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Venkateswara Swamy Temple', 'Venkateswara Swamy Temple', 'వేంకటేశ్వర స్వామి ఆలయం', 'वेंकटेश्वर स्वामी मंदिर', 'Home to pujas performed for prosperity, protection, and divine grace.', 'సంపద, రక్షణ మరియు దైవానుగ్రహం కోసం పూజలు నిర్వహించే ఆలయం.', 'समृद्धि, सुरक्षा और दिव्य कृपा के लिए पूजा की जाने वाली जगह।', 'assets/images/temples/venkateswara.jpg');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Maha Mrityunjaya Mahadev Mandir, Kashi', 'Maha Mrityunjaya Mahadev Mandir, Kashi', 'మహా మృత్యుంజయ మహాదేవ్ మందిర్, కాశీ', 'महा मृत्युंजय महादेव मंदिर, काशी', 'One of Kashi''s most revered sites for longevity and protection rituals.', 'దీర్ఘాయువు మరియు రక్షణ కోసం కాశీలోని అత్యంత పవిత్రమైన ఆలయాలలో ఒకటి.', 'दीर्घायु और सुरक्षा अनुष्ठानों के लिए काशी के सबसे पूजनीय स्थलों में से एक।', 'assets/images/temples/mrityunjaya.jpg');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Anjaneya Swamy Temple', 'Anjaneya Swamy Temple', 'ఆంజనేయ స్వామి ఆలయం', 'आंजनेय स्वामी मंदिर', 'A sacred site for pujas seeking courage, strength, and protection.', 'ధైర్యం, శక్తి మరియు రక్షణ కోసం పూజలు నిర్వహించే పవిత్ర స్థలం.', 'साहस, शक्ति और सुरक्षा की कामना करने वाली पूजाओं के लिए पवित्र स्थल।', 'assets/images/temples/anjaneya.jpg');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Basaveshwara Temple, Kukke Kshetra', 'Basaveshwara Temple, Kukke Kshetra', 'బసవేశ్వర ఆలయం, కుక్కె క్షేత్రం', 'बसवेश्वर मंदिर, कुक्के क्षेत्र', 'A revered kshetra for homams performed for family well-being.', 'కుటుంబ శ్రేయస్సు కోసం హోమాలు నిర్వహించే పూజనీయ క్షేత్రం.', 'पारिवारिक कल्याण के लिए होम किए जाने वाला पूजनीय क्षेत्र।', 'assets/images/temples/kukke.jpg');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Bhu Varaha Swamy Temple', 'Bhu Varaha Swamy Temple', 'భూ వరాహ స్వామి ఆలయం', 'भू वराह स्वामी मंदिर', 'Known for homams performed for stability and life''s obstacles.', 'స్థిరత్వం మరియు జీవితంలో అవరోధాల నివారణ కోసం హోమాలకు ప్రసిద్ధి.', 'स्थिरता और जीवन की बाधाओं के निवारण के लिए होम हेतु प्रसिद्ध।', 'assets/images/temples/varaha.jpg');
INSERT INTO cms_temples (id, name_en, name_te, name_hi, blurb_en, blurb_te, blurb_hi, image) VALUES ('Sri Bhramarambika Sametha Malleshwara Swamy Temple', 'Sri Bhramarambika Sametha Malleshwara Swamy Temple', 'శ్రీ భ్రమరాంబికా సమేత మల్లేశ్వర స్వామి ఆలయం', 'श्री भ्रमराम्बिका समेत मल्लेश्वर स्वामी मंदिर', 'A Guntur-region temple for seva performed for spiritual merit and peace.', 'ఆధ్యాత్మిక పుణ్యం మరియు శాంతి కోసం సేవలు నిర్వహించే గుంటూరు ప్రాంత ఆలయం.', 'आध्यात्मिक पुण्य और शांति के लिए सेवा करने वाला गुंटूर क्षेत्र का मंदिर।', 'assets/images/temples/malleshwara.jpg');
